import re, sys, os
here = os.path.dirname(os.path.abspath(__file__))
out = os.path.join(here, '..', 'markup5ever', 'generated')

names = []
seen = set()
for line in open(os.path.join(here, 'local_names.txt')):
    n = line.rstrip('\n')
    for v in (n, n.lower()):
        if v not in seen:
            seen.add(v); names.append(v)
namespaces = [("", ""), ("*", "*"), ("html", "http://www.w3.org/1999/xhtml"), ("xml", "http://www.w3.org/XML/1998/namespace"),
              ("xmlns", "http://www.w3.org/2000/xmlns/"), ("xlink", "http://www.w3.org/1999/xlink"),
              ("svg", "http://www.w3.org/2000/svg"), ("mathml", "http://www.w3.org/1998/Math/MathML")]

def ident(prefix, s):
    return prefix + '__' + '_'.join('%02X' % b for b in s.encode())

def rs(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'

def atom_set(kind, setname, macro, strings):
    o = []
    o.append('#[derive(Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord, Debug, Default)]\npub struct %s;\n' % setname)
    o.append('pub type %s = crate::atom::Atom<%s>;\n' % (kind, setname))
    o.append('impl crate::atom::StaticAtomSet for %s {\n' % setname)
    o.append('    const STRINGS: &\'static [&\'static str] = &[%s];\n' % ', '.join(rs(s) for s in strings))
    o.append('    fn index(s: &str) -> Option<u32> {\n        match s {\n')
    for i, s in enumerate(strings):
        o.append('            %s => Some(%d),\n' % (rs(s), i))
    o.append('            _ => None,\n        }\n    }\n}\n')
    p = 'ATOM_' + kind.upper()
    for i, s in enumerate(strings):
        o.append('pub const %s: %s = %s::pack_static(%d);\n' % (ident(p, s), kind, kind, i))
    o.append('#[macro_export]\nmacro_rules! %s {\n' % macro)
    for s in strings:
        o.append('    (%s) => { $crate::%s };\n' % (rs(s), ident(p, s)))
    o.append('}\n')
    return ''.join(o)

with open(os.path.join(out, 'atoms.rs'), 'w') as f:
    f.write('// Generated by vendor/tools/gen.py from local_names.txt.\n')
    f.write(atom_set('LocalName', 'LocalNameStaticSet', 'local_name', names))
    f.write(atom_set('Prefix', 'PrefixStaticSet', 'namespace_prefix', [p for p, _ in namespaces]))
    f.write(atom_set('Namespace', 'NamespaceStaticSet', 'namespace_url', [u for _, u in namespaces]))
    f.write('#[macro_export]\nmacro_rules! ns {\n')
    for p, u in namespaces:
        f.write('    (%s) => { $crate::namespace_url!(%s) };\n' % (p, rs(u)))
    f.write('}\n')

src = open(os.path.join(here, 'entities.rs')).read()
ents = {}
for m in re.finditer(r'\("&([^"]*)",\s*(\d+),\s*(\d+)\)', src):
    ents[m.group(1)] = (int(m.group(2)), int(m.group(3)))
assert len(ents) == 2231, len(ents)
full = dict(ents)
for k in list(ents):
    for n in range(1, len(k)):
        full.setdefault(k[:n], (0, 0))
full.setdefault('', (0, 0))
keys = sorted(full, key=lambda s: s.encode())
with open(os.path.join(out, 'entities.rs'), 'w') as f:
    f.write('// Generated by vendor/tools/gen.py from entities.rs: every entity name without its "&", plus every prefix\n// of one mapped to (0, 0), sorted by bytes for binary search.\n')
    f.write('pub static NAMED_ENTITIES_SORTED: [(&str, (u32, u32)); %d] = [\n' % len(keys))
    for k in keys:
        f.write('    (%s, (%d, %d)),\n' % (rs(k), full[k][0], full[k][1]))
    f.write('];\n')
print(len(names), 'local names,', len(keys), 'entity keys')
